import {describe, expect, test} from "bun:test";
import {readFile} from "node:fs/promises";
import {fileURLToPath} from "node:url";
import {convert} from "./common/convert.ts";

// testdata/convert.pdf is generated by ghostscript from PostScript: page 1 is
// text, page 2 is a 4x4 checkerboard image with no text layer.
const out = await convert(fileURLToPath(new URL("testdata/convert.pdf", import.meta.url)));

describe("convert", () => {
  test("extracts the text layer of a text page", () => {
    expect(out).toContain("Hello from a text layer\nSecond line of body text");
  });

  test("links a page without a text layer to a rendered png", () => {
    expect(out).not.toContain("base64");
    const link = out.match(/!\[page 2\]\(([^)]+)\)/);
    expect(link).not.toBeNull();
    expect(link![1]).toMatch(/\/page-2\.png$/);
  });

  test("writes the png the link points at", async () => {
    const png = await readFile(out.match(/!\[page 2\]\(([^)]+)\)/)![1]!);
    expect([...png.subarray(0, 4)]).toEqual([0x89, 0x50, 0x4e, 0x47]);
  });
});
